window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-34228d9ef970a495"]={"versions": [{"id": "FIG-34228d9ef970a495", "releases": ["R4.0.3", "R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Zustandsdiagramm (<code>sm statemachine for direct function calls of an ExecutableEntity execution-instance</code>) im Kontext der AUTOSAR RTE (Runtime Environment) und des SchM (Basic Software Scheduler). Es spezifiziert den formalen Lebenszyklus und die Zustandsübergänge einer Instanz einer <code>ExecutableEntity</code> (z. B. Runnable Entity oder BSW Schedulable Entity), wenn diese über direkte Funktionsaufrufe statt über ein separates Task-Mapping ausgeführt wird.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Übergeordneter Zustand</strong>: <code>ExecutableEntity execution-instance is schedulable</code> mit den Randbedingungen / Constraints:</li>\n<li><code>{queue length == 0}</code></li>\n<li><code>{debounceTimer == 0}</code></li>\n<li><code>{canBeInvocecConcurrently == true}</code></li>\n<li><code>{runnable not mapped to task}</code></li>\n<li><strong>Regionen / Unterzustände in <code>Main</code></strong>:</li>\n<li><code>suspended</code>: Ruhezustand der Ausführungsinstanz (initial über Pseudo-Startzustand erreichbar).</li>\n<li><code>started</code>: Zusammengesetzter Zustand der aktiven Ausführung mit internem Startzustand, der direkt in <code>running</code> übergeht.</li>\n<li><code>running</code>: Aktive Funktionsausführung auf der CPU.</li>\n<li><code>waiting</code>: Wartezustand auf ein Ereignis oder eine Ressource.</li>\n<li><code>preempted</code>: Unterbrochener Zustand, wenn der aufrufende Kontext verdrängt wurde.</li>\n<li><strong>Konzeptuelle Zuordnung</strong>: Die gestrichelte Umrandung <code>corresponds to task state \"ready\"</code> fasst die Zustände bzw. den Eintritt in <code>preempted</code> zusammen.</li>\n<li><strong>Schnittstellen & Wächterbedingungen</strong>: Guards auf Partitions-Ebene (<code>[RTE / SchM of the partition is running]</code>, <code>[RTE / SchM of the partition is stopped]</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Lebenszyklus der Partition</strong>:</li>\n<li>Der globale Startknoten führt bei Bedingung <code>[RTE / SchM of the partition is running]</code> in den Zustand <code>ExecutableEntity execution-instance is schedulable</code>.</li>\n<li>Beim Stoppen der Partition (<code>[RTE / SchM of the partition is stopped]</code>) wechselt die Instanz in den Endzustand.</li>\n<li><strong>Zustandsübergänge in <code>Main</code></strong>:</li>\n<li>Initialzustand wechselt nach <code>suspended</code>.</li>\n<li><code>suspended</code> -> <code>preempted</code>: Trigger <code>activate</code> (Instanz wird aufrufbar / aktiviert).</li>\n<li><code>started</code> (Initialknoten) -> <code>running</code>: Beginn der Ausführung des direkten Funktionsaufrufs.</li>\n<li><code>running</code> -> <code>preempted</code>: Trigger <code>preempt</code> (Verdrängung des ausführenden Kontexts).</li>\n<li><code>preempted</code> -> <code>running</code>: Trigger <code>resume</code> (Fortsetzung der Ausführung).</li>\n<li><code>running</code> -> <code>waiting</code>: Trigger <code>wait</code> (Blockieren auf Ereignis).</li>\n<li><code>waiting</code> -> <code>preempted</code>: Trigger <code>release</code> (Ereignis eingetroffen / Ressource verfügbar).</li>\n<li><code>running</code> -> <code>suspended</code>: Trigger <code>terminate</code> (Beendigung des Funktionsaufrufs).</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Definiert das normativ geforderte Scheduling-Verhalten für ungemappte Runnables mit direkter Funktionsaufrufsemantik (<code>canBeInvokedConcurrently == true</code>).</li>\n<li>Verdeutlicht für RTE-Implementierer und BSW-Entwickler, dass eine per Funktionsaufruf implementierte Ausführungsinstanz dennoch die logischen Phasen <code>preempted</code> und <code>waiting</code> durchlaufen kann, die dem Betriebssystem-Taskstatus <code>ready</code> bzw. Verdrängungssituationen des Träger-Kontexts entsprechen.</li>\n<li>Bei Partition-Stopp werden schedulbare Instanzen unverzüglich terminiert.</li>\n</ul>"}, {"id": "FIG-8ad865adf60aa8bc", "releases": ["R4.2.2", "R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Zustandsdiagramm (<code>sm statemachine for direct function calls of an ExecutableEntity execution-instance</code>) im Kontext der AUTOSAR RTE (Runtime Environment) und des SchM (Basic Software Scheduler). Es spezifiziert den formalen Lebenszyklus und die Zustandsübergänge einer Instanz einer <code>ExecutableEntity</code> (z. B. Runnable Entity oder BSW Schedulable Entity), wenn diese über direkte Funktionsaufrufe statt über ein separates Task-Mapping ausgeführt wird.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Übergeordneter Zustand</strong>: <code>ExecutableEntity execution-instance is schedulable</code> mit den Randbedingungen / Constraints:</li>\n<li><code>{queue length == 0}</code></li>\n<li><code>{debounceTimer == 0}</code></li>\n<li><code>{canBeInvocecConcurrently == true}</code></li>\n<li><code>{runnable not mapped to task}</code></li>\n<li><strong>Regionen / Unterzustände in <code>Main</code></strong>:</li>\n<li><code>suspended</code>: Ruhezustand der Ausführungsinstanz (initial über Pseudo-Startzustand erreichbar).</li>\n<li><code>started</code>: Zusammengesetzter Zustand der aktiven Ausführung mit internem Startzustand, der direkt in <code>running</code> übergeht.</li>\n<li><code>running</code>: Aktive Funktionsausführung auf der CPU.</li>\n<li><code>waiting</code>: Wartezustand auf ein Ereignis oder eine Ressource.</li>\n<li><code>preempted</code>: Unterbrochener Zustand, wenn der aufrufende Kontext verdrängt wurde.</li>\n<li><strong>Konzeptuelle Zuordnung</strong>: Die gestrichelte Umrandung <code>corresponds to task state \"ready\"</code> fasst die Zustände bzw. den Eintritt in <code>preempted</code> zusammen.</li>\n<li><strong>Schnittstellen & Wächterbedingungen</strong>: Guards auf Partitions-Ebene (<code>[RTE / SchM of the partition is running]</code>, <code>[RTE / SchM of the partition is stopped]</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Lebenszyklus der Partition</strong>:</li>\n<li>Der globale Startknoten führt bei Bedingung <code>[RTE / SchM of the partition is running]</code> in den Zustand <code>ExecutableEntity execution-instance is schedulable</code>.</li>\n<li>Beim Stoppen der Partition (<code>[RTE / SchM of the partition is stopped]</code>) wechselt die Instanz in den Endzustand.</li>\n<li><strong>Zustandsübergänge in <code>Main</code></strong>:</li>\n<li>Initialzustand wechselt nach <code>suspended</code>.</li>\n<li><code>suspended</code> -> <code>preempted</code>: Trigger <code>activate</code> (Instanz wird aufrufbar / aktiviert).</li>\n<li><code>started</code> (Initialknoten) -> <code>running</code>: Beginn der Ausführung des direkten Funktionsaufrufs.</li>\n<li><code>running</code> -> <code>preempted</code>: Trigger <code>preempt</code> (Verdrängung des ausführenden Kontexts).</li>\n<li><code>preempted</code> -> <code>running</code>: Trigger <code>resume</code> (Fortsetzung der Ausführung).</li>\n<li><code>running</code> -> <code>waiting</code>: Trigger <code>wait</code> (Blockieren auf Ereignis).</li>\n<li><code>waiting</code> -> <code>preempted</code>: Trigger <code>release</code> (Ereignis eingetroffen / Ressource verfügbar).</li>\n<li><code>running</code> -> <code>suspended</code>: Trigger <code>terminate</code> (Beendigung des Funktionsaufrufs).</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Definiert das normativ geforderte Scheduling-Verhalten für ungemappte Runnables mit direkter Funktionsaufrufsemantik (<code>canBeInvokedConcurrently == true</code>).</li>\n<li>Verdeutlicht für RTE-Implementierer und BSW-Entwickler, dass eine per Funktionsaufruf implementierte Ausführungsinstanz dennoch die logischen Phasen <code>preempted</code> und <code>waiting</code> durchlaufen kann, die dem Betriebssystem-Taskstatus <code>ready</code> bzw. Verdrängungssituationen des Träger-Kontexts entsprechen.</li>\n<li>Bei Partition-Stopp werden schedulbare Instanzen unverzüglich terminiert.</li>\n</ul>"}], "trans": [{"from": "FIG-34228d9ef970a495", "to": "FIG-8ad865adf60aa8bc", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
